INSERT INTO HEROES (opp_id, kind, name, amount, probability, complexity_score, cheap_verdict, cheap_primary_blocker, cheap_next_best_action, cheap_reasoning, premium_verdict, premium_primary_blocker, premium_next_best_action, premium_reasoning, routed_tier, routed_reason, routed_evidence) VALUES
('OPP-001', 'settled', 'Meridian Health -- Platform Renewal', 5200000, 0.99, 0, 'NO_ACTION_NEEDED', 'NONE', 'Monitor the opportunity for the expected countersignature from the customer.', 'The opportunity is in the CONTRACT stage with a high close probability of 0.99 and no active risk flags. The legal review is complete, MSA redlines have been signed off, and a PO has been raised in the customer''s system. The rep expects countersignature this month, which is the only remaining step before closing the deal.', 'NO_ACTION_NEEDED', 'NONE', 'Monitor for countersignature and ensure contract execution is completed this month as expected.', 'This opportunity meets all criteria for no action needed: it is in CONTRACT stage with no active risk flags and a 0.99 close probability. Legal review is complete, the PO is raised, and CFO sponsorship provides strong executive alignment. The deal is effectively won and awaiting final paperwork.', 'cheap', 'settled: probability at or above high-confidence threshold', '{"probability": 0.99, "high_confidence_threshold": 0.98, "low_confidence_threshold": 0.1, "complexity_threshold": 4}'),
('OPP-002', 'complex', 'Northwind Logistics -- Analytics Expansion', 400000, 0.52, 4, 'AT_RISK', 'SECURITY_LEGAL', 'Escalate the security review by reaching out to the InfoSec team to understand the status of the data residency question and provide a clear resolution path.', 'The deal is at risk due to the security review being stalled for three weeks, with no ETA from the InfoSec team. The presence of a competitor, DataRival, also adds to the risk. The champion, Dir of Ops, is enthusiastic, but the lack of engagement from the VP Finance and the non-started procurement portal registration further complicate the situation.', 'AT_RISK', 'SECURITY_LEGAL', 'Escalate the data residency blocker by arranging a joint call between your security architect, their InfoSec lead, and the champion to establish a resolution timeline.', 'The security review has been stalled for three weeks with no ETA, blocking all downstream progress including procurement and economic buyer engagement. Multiple active risk flags exist, but the security/legal issue is the immediate gate preventing the deal from advancing. Without resolving data residency, procurement cannot start and the VP Finance will not engage.', 'premium', 'high decision complexity: unresolved evidence to synthesize', '{"complexity_score": 4, "high_confidence_threshold": 0.98, "low_confidence_threshold": 0.1, "complexity_threshold": 4}'),
('OPP-003', 'contestable', 'Castellan Insurance -- Claims AI Pilot', 750000, 0.58, 3, 'AT_RISK', 'CHAMPION_LOSS', 'Schedule a call with the Claims VP to understand the current status of the budget decision process and the scope of the pilot.', 'The champion has moved into a new role with narrower budget authority, and the budget decision process is unclear. The Claims VP wants a full-department rollout, but the IT sponsor insists on a 10-seat pilot, and the two have not reconciled scope. The incumbent vendor''s renewal is also running in parallel, adding to the risk of losing the deal.', 'AT_RISK', 'ECONOMIC_BUYER', 'Facilitate a joint scoping meeting with the Claims VP and IT sponsor to align on pilot scope and identify the actual budget authority before any commercial discussion.', 'The deal is marked as negotiation stage but lacks a clear economic buyer after the champion''s role change, and no commercial terms have been discussed. The conflicting scope expectations between Claims VP and IT sponsor, combined with unclear budget routing through an IT steering committee, create fundamental deal structure risk that must be resolved before forecasting can be trusted.', 'balanced', 'default tier: contested but not high-complexity', '{"complexity_score": 3, "high_confidence_threshold": 0.98, "low_confidence_threshold": 0.1, "complexity_threshold": 4}');
